static int cmp_edge(const void *a, const void *b) {
    ll x = ((const Edge *)a)->w;
    ll y = ((const Edge *)b)->w;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int find_set(DSU *dsu, int x) {
    if (dsu[x].parent != x)
        dsu[x].parent = find_set(dsu, dsu[x].parent);
    return dsu[x].parent;
}

static int union_set(DSU *dsu, int a, int b) {
    a = find_set(dsu, a);
    b = find_set(dsu, b);
    if (a == b) return 0;

    if (dsu[a].rank < dsu[b].rank) {
        dsu[a].parent = b;
    } else if (dsu[a].rank > dsu[b].rank) {
        dsu[b].parent = a;
    } else {
        dsu[b].parent = a;
        dsu[a].rank++;
    }
    return 1;
}

