/*
Minimum Spanning Tree with Kruskal.

The statement describes islands and bridge construction with minimum total cost
while keeping all islands connected. This is the classic MST problem.

Input format is not explicitly shown in the prompt, so we assume the standard:
n m
u v w   (m lines)

where:
- n = number of islands (vertices)
- m = number of possible bridges (edges)
- u, v are endpoints
- w is construction cost

Output:
- minimum total cost if all islands can be connected
- otherwise "IMPOSSIBLE"

This matches the usual formulation of such problems.
*/

struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }

    void init(int n) {
        p.resize(n + 1);
        sz.assign(n + 1, 1);
        iota(p.begin(), p.end(), 0);
    }

    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }

    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};

struct Edge {
    int u, v;
    long long w;
    bool operator<(const Edge& other) const {
        return w < other.w;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

