public class SinkingIslands {
    static class Edge implements Comparable<Edge> {
        int u, v, w;
        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
        public int compareTo(Edge other) {
            return this.w - other.w;
        }
    }

    static int[] parent, rank;

    static int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    static boolean union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return false;
        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
        } else if (rank[rx] > rank[ry]) {
            parent[ry] = rx;
        } else {
            parent[ry] = rx;
            rank[rx]++;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        List<Edge> edges = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            int w = Integer.parseInt(st.nextToken());
            edges.add(new Edge(u, v, w));
        }

        int q = Integer.parseInt(br.readLine());
        int[] queries = new int[q];
        for (int i = 0; i < q; i++) {
            queries[i] = Integer.parseInt(br.readLine()) - 1;
        }

        // Sort edges by weight for MST
        Collections.sort(edges);

        // Initially all islands are present
        boolean[] active = new boolean[n];
        Arrays.fill(active, true);

        // Mark islands that will sink as inactive (we process in reverse)
        for (int idx : queries) {
            active[idx] = false;
        }

        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        // Build MST with initially active islands
        int totalCost = 0;
        int components = 0;
        for (int i = 0; i < n; i++) if (active[i]) components++;

        for (Edge e : edges) {
            if (active[e.u] && active[e.v] && union(e.u, e.v)) {
                totalCost += e.w;
                components--;
            }
        }

        long[] result = new long[q];
        // Process in reverse: add islands back
        for (int i = q - 1; i >= 0; i--) {
            result[i] = (components == 1) ? totalCost : -1;
            int island = queries[i];
            active[island] = true;
            components++;
            for (Edge e : edges) {
                if ((e.u == island && active[e.v]) || (e.v == island && active[e.u])) {
                    if (active[e.u] && active[e.v] && union(e.u, e.v)) {
                        totalCost += e.w;
                        components--;
                    }
                }
            }
        }

        // Output results in original order
        for (long res : result) {
            System.out.println(res);
        }
    }
}

