        return parent[x];
    }

    static boolean union(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;
        if (rank[px] < rank[py]) { int t = px; px = py; py = t; }
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        int[] sinkTime = new int[N + 1];
        for (int i = 1; i <= N; i++) sinkTime[i] = Integer.parseInt(br.readLine().trim());

        List<int[]>[] adj = new List[N + 1];
        for (int i = 1; i <= N; i++) adj[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            adj[u].add(new int[]{v, c});
            adj[v].add(new int[]{u, c});
        }

        parent = new int[N + 1]; rank = new int[N + 1];
        for (int i = 1; i <= N; i++) { parent[i] = i; rank[i] = 0; }

        Integer[] order = new Integer[N];
        for (int i = 0; i < N; i++) order[i] = i + 1;
        Arrays.sort(order, (a, b) -> sinkTime[a] - sinkTime[b]);

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        long totalCost = 0;
        int edgesUsed = 0;

        for (int idx = 0; idx < N; idx++) {
            int island = order[idx];
            for (int[] e : adj[island]) pq.offer(new int[]{e[0], e[1], island});
            // Connect island to cheapest available
            while (!pq.isEmpty() && find(island) != find(pq.peek()[0]) || 
                   !pq.isEmpty() && find(pq.peek()[0]) == find(pq.peek()[2])) {
                // just drain and try
                break;
            }
        }
        // Redo with proper MST
        parent = new int[N + 1]; rank = new int[N + 1];
        for (int i = 1; i <= N; i++) parent[i] = i;
        pq.clear(); totalCost = 0; edgesUsed = 0;
        for (int idx = 0; idx < N; idx++) {
            int island = order[idx];
            for (int[] e : adj[island]) pq.offer(new int[]{e[0], e[1]});
            while (!pq.isEmpty() && edgesUsed < N - 1) {
                int[] e = pq.poll();
                if (union(e[0], e[1])) { totalCost += e[1]; edgesUsed++; }
            }
        }
        System.out.println(totalCost);
    }
}

