/*
 * Sinking Islands
 *
 * Interpretation used:
 * - There are N islands and M possible bridges.
 * - Each bridge connects two islands with a construction cost.
 * - Build bridges so that all islands stay connected with minimum total cost.
 *
 * This is the Minimum Spanning Tree problem.
 * We solve it with Kruskal's algorithm + Disjoint Set Union.
 *
 * Input format assumed:
 * N M
 * u1 v1 w1
 * ...
 * uM vM wM
 *
 * Output:
 * Minimum total cost if all islands can be connected, otherwise "impossible".
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge implements Comparable<Edge> {
        int u, v;
        long w;

        Edge(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }

        public int compareTo(Edge other) {
            return Long.compare(this.w, other.w);
        }
    }

    static class DSU {
        int[] parent, rank;

        DSU(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 0; i <= n; i++) parent[i] = i;
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        boolean union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return false;

            if (rank[ra] < rank[rb]) {
                parent[ra] = rb;
            } else if (rank[ra] > rank[rb]) {
                parent[rb] = ra;
            } else {
                parent[rb] = ra;
                rank[ra]++;
            }
            return true;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = fs.nextInt();

        Edge[] edges = new Edge[m];
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            long w = fs.nextLong();
            edges[i] = new Edge(u, v, w);
        }

        Arrays.sort(edges);
        DSU dsu = new DSU(n);

        long total = 0;
        int used = 0;

        for (Edge e : edges) {
            if (dsu.union(e.u, e.v)) {
                total += e.w;
                used++;
                if (used == n - 1) break;
            }
        }

        if (used == n - 1) {
            System.out.println(total);
        } else {
            System.out.println("impossible");
        }
    }
}

