import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    edges = []
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        edges.append((w, u - 1, v - 1))

    # Kruskal's algorithm for Minimum Spanning Tree
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True

    edges.sort()
    total = 0
    used = 0

    for w, u, v in edges:
        if union(u, v):
            total += w
            used += 1
            if used == n - 1:
                break

    # If graph is disconnected, spanning tree is impossible
    if used != n - 1:
        print("IMPOSSIBLE")
    else:
        print(total)

